-- 032_vuln_target_map.sql
-- Seed: npm packages with a disclosed CWE-22/78/918 history (GitHub Advisory
-- Database, gathered 2026-09-08). credential_score ranks reputation value;
-- pays is false across this set — npm OSS vuln disclosure is unpaid (verified:
-- budibase and n8n, the heaviest company-backed offenders, run no paid program).
-- This is a hunting/target inventory for future runs, not a payer list.

CREATE TABLE IF NOT EXISTS vuln_target_map (
  ecosystem TEXT NOT NULL DEFAULT 'npm',
  package TEXT NOT NULL,
  cwe_classes TEXT[] NOT NULL DEFAULT '{}',
  advisory_count INTEGER NOT NULL DEFAULT 0,
  worst_severity TEXT,
  credential_score NUMERIC(4,2) NOT NULL DEFAULT 0,
  pays BOOLEAN NOT NULL DEFAULT false,
  pays_via TEXT,
  company_backed BOOLEAN NOT NULL DEFAULT false,
  source TEXT NOT NULL DEFAULT 'ghsa',
  gathered_on DATE NOT NULL DEFAULT '2026-09-08',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (ecosystem, package)
);
CREATE INDEX IF NOT EXISTS idx_vuln_target_map_rank ON vuln_target_map(pays DESC, credential_score DESC);

